/bin/bash -lc "cd /workspace && python - <<'PY'
import fitz
doc=fitz.open('paper.pdf')
for i,p in enumerate(doc):
    for l in p.get_links():
        uri=l.get('uri')
        if uri:
            print(i+1, repr(uri))
