/bin/bash -lc "cd /workspace && curl -sL \"https://raw.githubusercontent.com/kundajelab/scATAC-reprog/master/src/analysis/20230814_exports/scATAC_data.ipynb\" -o scATAC_data.ipynb && python - <<'PY'
import json
nb=json.load(open('scATAC_data.ipynb'))
for i,c in enumerate(nb['cells']):
 if c.get('cell_type')=='code':
  src=''.join(c.get('source',[]))
  if any(k in src for k in ['peak','cluster','label','write','tsv','bed','csv']):
   print('\\n---CELL',i,'---')
   print(src[:2000])
PY"

