/bin/bash -lc "cd /workspace && python - <<'PY'
import json
nb=json.load(open('scATAC_data.ipynb'))
for i,c in enumerate(nb['cells']):
 if c.get('cell_type')=='code':
  src=''.join(c.get('source',[]))
  if 'table(peaks_w_set"'$set)'"' in src:
   print('CELL',i)
   for o in c.get('outputs',[]):
    print(o.keys())
    if 'data' in o:
     print(o['data'].get('text/plain'))
    if 'text' in o:
     print(o['text'])
PY"

